"Разность двух чисел равна 47 042, вычитаемое — 8 890. Чему равно уменьшаемое?": "两个数的差是47 042，减数是8 890。被减数是多少？",
"Ученики, играющие в футбол, и ученики, поющие в хоре (есть играющие и поющие)": "踢足球的学生和在合唱团唱歌的学生（有的既踢球又唱歌）",
"Привет! Это Барсик. Сегодня считаем устно большие числа. Нажимай на карточки.": "你好！我是巴尔西克。今天我们来口算大数。点一点卡片吧。",
"Изменились все цифры после сотен: 47 386 ≈ 47 400. Значит, округлили до сотен.": "百位之后的所有数字都变了：47 386 ≈ 47 400。说明是四舍五入到百位。",
"Если двое отъезжают от одного места в разные стороны, то их скорости вычитают.": "如果两个人从同一地点向相反方向出发，就把他们的速度相减。",
"57 336 тенге разделили поровну между 8 друзьями. Сколько тенге получил каждый?": "57 336坚戈平均分给8个朋友。每人得到多少坚戈？",
"57 336 тенге разделили поровну между 8 друзьями. Сколько тенге получил каждый?": "57 336坚戈平均分给8个朋友。每人得到多少坚戈？",
"Неизвестное уменьшаемое равно разности плюс вычитаемое: 9 000 + 4 500 = 13 500.": "未知的被减数等于差加减数：9 000 + 4 500 = 13 500。",
"Даны A = { 1; 2; 3; 4 }, B = { 3; 4; 5 }, C = { 4; 7; 8 }. Найдите (A ∪ B) ∪ C.": "已知A = { 1; 2; 3; 4 }，B = { 3; 4; 5 }，C = { 4; 7; 8 }。求(A ∪ B) ∪ C。",
"Размеры контейнера: 50 дм × 10 дм × 10 дм. Найди его объём в кубических метрах.": "集装箱的尺寸：50分米 × 10分米 × 10分米。求它的体积，单位是立方米。",
"Размеры контейнера: 50 дм × 10 дм × 10 дм. Найди его объём в кубических метрах.": "集装箱的尺寸：50分米 × 10分米 × 10分米。求它的体积，单位是立方米。",
"Частное умножаем на делитель и прибавляем остаток. 99 · 10 = 990, 990 + 8 = 998.": "把商乘以除数，再加上余数。99 · 10 = 990，990 + 8 = 998。",
"V = 5 · 8 · 3 = 120 дм³. 1 дм³ вмещает 1 л воды, значит в аквариум входит 120 л.": "V = 5 · 8 · 3 = 120立方分米。1立方分米能装1升水，所以鱼缸能装120升。",
"Неизвестное вычитаемое равно уменьшаемому без разности: 50 000 − 18 000 = 32 000.": "未知的减数等于被减数减去差：50 000 − 18 000 = 32 000。",
"Привет! Это Барсик. Сегодня находим доли часа, суток и года. Нажимай на карточки.": "你好！我是巴尔西克。今天我们来求小时、天和年的几分之几。点一点卡片吧。",
"В числе 5 307 пять тысяч, три сотни, ноль десятков и семь единиц: 5 000 + 300 + 7.": "数5 307有五个千、三个百、零个十和七个一：5 000 + 300 + 7。",
"В числе 5 307 пять тысяч, три сотни, ноль десятков и семь единиц: 5 000 + 300 + 7.": "数5 307有五个千、三个百、零个十和七个一：5 000 + 300 + 7。",
"Если общих элементов нет, круги рисуют отдельно. Овощи и фрукты — такие множества.": "如果没有公共元素，两个圆就分开画。蔬菜和水果就是这样的集合。",
"Площадь измеряют в квадратных единицах (см², м²), а объём — в кубических (см³, м³).": "面积用平方单位（平方厘米、平方米）来量，体积用立方单位（立方厘米、立方米）来量。",
"Скобки по-разному, результат тот же — сочетательное свойство. Знак ∪ — объединение.": "括号的位置不同，结果相同——这是结合律。符号 ∪ 表示并集。",
"Остаток всегда меньше делителя. Остаток 9 не меньше 7, значит, получиться не может.": "余数总是小于除数。余数9不小于7，所以不可能得到。",
"Один велосипедист едет впереди, а второй, более быстрый, едет за ним в ту же сторону": "一个骑自行车的人在前面，另一个骑得更快的人在他后面，朝同一个方向骑",
"Дано множество A = {Н, Т, К, О, Б, П}. Какое из множеств — подмножество множества A?": "已知集合A = {Н, Т, К, О, Б, П}。下面哪个集合是集合A的子集？",
"Например, 320 000 + 60 000 = 380 000: складываем 32 десятка тысяч и 6 десятков тысяч.": "例如，320 000 + 60 000 = 380 000：把32个万和6个万相加。",
"x — неизвестное уменьшаемое: x = разность + вычитаемое. x = 30 787 + 38 830 = 69 617.": "x是未知的被减数：x = 差 + 减数。x = 30 787 + 38 830 = 69 617。",
"x — неизвестное уменьшаемое: x = разность + вычитаемое. x = 30 787 + 38 830 = 69 617.": "x是未知的被减数：x = 差 + 减数。x = 30 787 + 38 830 = 69 617。",
