"Даны M = { 2; 4; 6; 8; 10 } и K = { 4; 8; 12 }. Сколько элементов в объединении M ∪ K?": "已知M = { 2; 4; 6; 8; 10 }和K = { 4; 8; 12 }。并集M ∪ K有多少个元素？",
