"На 10 делятся числа, которые оканчиваются на 0. Подходит цифра 0: 35 820 : 10 = 3 582.": "末位是0的数能被10整除。数字0合适：35 820 : 10 = 3 582。",
"Выполнять деление многозначных чисел на 10, 100, 1 000 с остатком и проверять результат": "做多位数除以10、100、1 000的有余数除法，并检验结果",
"Выполнять деление многозначных чисел на 10, 100, 1 000 с остатком и проверять результат": "做多位数除以10、100、1 000的有余数除法，并检验结果",
"Турист из Алматы в Москве купил сувенир за 360 руб. и дал 500 руб. Сколько рублей сдачи?": "从阿拉木图来的游客在莫斯科花360卢布买了一件纪念品，付了500卢布。找回多少卢布？",
"Площадь одной клетки: 10 · 10 = 100 мм². Клеток 21. 21 · 100 = 2 100. Площадь 2 100 мм².": "一个方格的面积：10 · 10 = 100平方毫米。有21个方格。21 · 100 = 2 100。面积是2 100平方毫米。",
"Площадь одной клетки: 10 · 10 = 100 мм². Клеток 21. 21 · 100 = 2 100. Площадь 2 100 мм².": "一个方格的面积：10 · 10 = 100平方毫米。有21个方格。21 · 100 = 2 100。面积是2 100平方毫米。",
"999 меньше 1 000, поэтому такой остаток возможен. Например, 5 999 : 1 000 = 5 (ост. 999).": "999小于1 000，所以这样的余数是可能的。例如，5 999 : 1 000 = 5（余999）。",
"999 меньше 1 000, поэтому такой остаток возможен. Например, 5 999 : 1 000 = 5 (ост. 999).": "999小于1 000，所以这样的余数是可能的。例如，5 999 : 1 000 = 5（余999）。",
