"Последнюю цифру суммы даёт разряд единиц: 1 + 0 = 1, в единицах пишем 1. Всё число: 81 361": "和的最后一位数字由个位给出：1 + 0 = 1，个位写1。整个数是81 361",
"Последнюю цифру суммы даёт разряд единиц: 1 + 0 = 1, в единицах пишем 1. Всё число: 81 361": "和的最后一位数字由个位给出：1 + 0 = 1，个位写1。整个数是81 361",
"Первая часть: 80 · 4 = 320 км. Вторая часть: 40 · 2 = 80 км. Весь путь: 320 + 80 = 400 км.": "第一段：80 · 4 = 320千米。第二段：40 · 2 = 80千米。全程：320 + 80 = 400千米。",
"Сначала считаем кубики в одном слое: длина · ширина. Потом умножаем на число слоёв — высоту": "先算一层有几个小方块：长 · 宽。再乘层数——也就是高",
"Площадь всего прямоугольника: 15 · 6 = 90 м². Площадь выреза: 4 · 2 = 8 м². 90 − 8 = 82 м².": "整个长方形的面积：15 · 6 = 90平方米。缺口的面积：4 · 2 = 8平方米。90 − 8 = 82平方米。",
"В магазине предлагают: 750 тг за 3 кг мандаринов или 850 тг за 5 кг. Где мандарины дешевле?": "商店里有：3千克橘子750坚戈，或5千克850坚戈。哪种橘子更便宜？",
"В магазине предлагают: 750 тг за 3 кг мандаринов или 850 тг за 5 кг. Где мандарины дешевле?": "商店里有：3千克橘子750坚戈，或5千克850坚戈。哪种橘子更便宜？",
"Если из суммы вычесть одно слагаемое, получится другое. Например, 12 + 5 = 17, а 17 − 5 = 12": "如果从和里减去一个加数，就得到另一个加数。例如，12 + 5 = 17，而17 − 5 = 12",
"Объединение: { 2; 4; 6; 8; 10; 12 }. Общие элементы 4 и 8 считаем один раз, поэтому всего 6.": "并集：{ 2; 4; 6; 8; 10; 12 }。公共元素4和8只算一次，所以一共6个。",
"Площадь листа: 14 · 10 = 140 м². Площадь выреза: 7 · 5 = 35 м². Осталось: 140 − 35 = 105 м².": "铁皮的面积：14 · 10 = 140平方米。缺口的面积：7 · 5 = 35平方米。剩下：140 − 35 = 105平方米。",
"Каждый скрипач — музыкант, значит, всё множество скрипачей лежит внутри множества музыкантов.": "每个小提琴手都是音乐家，所以小提琴手的整个集合都在音乐家集合的里面。",
"В 1 километре 1 000 метров, в 1 часе 60 минут. Поэтому 36 км/ч = 36 · 1 000 : 60 = 600 м/мин.": "1千米有1 000米，1小时有60分钟。所以36千米/时 = 36 · 1 000 : 60 = 600米/分。",
"В 1 километре 1 000 метров, в 1 часе 60 минут. Поэтому 36 км/ч = 36 · 1 000 : 60 = 600 м/мин.": "1千米有1 000米，1小时有60分钟。所以36千米/时 = 36 · 1 000 : 60 = 600米/分。",
"Решать задачи с помощью кругов Эйлера и подсчитывать число элементов объединения и пересечения": "用欧拉圆解题，并数出并集和交集的元素个数",
"От школы до дома 1 360 м. Тимур идёт со скоростью 80 м/мин. За сколько минут он дойдёт до дома?": "从学校到家有1 360米。铁木尔的速度是80米/分。他走多少分钟能到家？",
"От школы до дома 1 360 м. Тимур идёт со скоростью 80 м/мин. За сколько минут он дойдёт до дома?": "从学校到家有1 360米。铁木尔的速度是80米/分。他走多少分钟能到家？",
"Тех, кто занимается и тем и другим, при сложении посчитали дважды. 18 + 12 − 7 = 23. Ответ: 23.": "两样都参加的人，相加时被数了两次。18 + 12 − 7 = 23。答案：23。",
"Наибольшая сумма в разряде: 9 + 9 + 1 = 19. Это 1 десяток и 9 единиц, значит переносим только 1.": "数位上最大的和：9 + 9 + 1 = 19。这是1个十和9个一，所以只进1。",
"Объём измеряют кубическими единицами: кубический сантиметр, кубический дециметр, кубический метр.": "体积用立方单位来量：立方厘米、立方分米、立方米。",
"Считаем разряды справа: 7 — единицы, 0 — десятки, 2 — сотни, 5 — единицы тысяч, 8 — десятки тысяч.": "从右往左数数位：7是个位，0是十位，2是百位，5是千位，8是万位。",
"Если цена та же, а количество товара стало больше в 4 раза, стоимость тоже станет больше в 4 раза.": "如果单价不变，商品的数量变成原来的4倍，总价也会变成原来的4倍。",
